theorem Summable.exists_max_norm {ι M : Type*} [NormedAddCommGroup M] {g : ι → M}
    (hg : Summable g) {i₁ : ι} (hi₁ : g i₁ ≠ 0) :
    ∃ i₀, g i₀ ≠ 0 ∧ ∀ i, ‖g i‖ ≤ ‖g i₀‖

theorem exists_max_norm_laurent {K : Type*} [NormedField K] {c : ℤ → K} {u : Kˣ}
    (hsum : Summable fun n : ℤ => c n * (u : K) ^ n) {m : ℤ} (hm : c m ≠ 0) :
    ∃ n₀ : ℤ, c n₀ ≠ 0 ∧ ∀ n : ℤ, ‖c n * (u : K) ^ n‖ ≤ ‖c n₀ * (u : K) ^ n₀‖

private theorem alpha_wCoeff_eq_upper {c : ℤ → K} {α : K} (hα0 : α ≠ 0) (n : ℤ) :
    α ^ (n + 1) * wCoeff c α n
      = ∑' m : ℤ, (Set.Ioi n).indicator (fun m => c m * α ^ m) m

private lemma mA_shift (N i j : ℕ) :
    mA N i j = ∑ q ∈ (tateQuad N).filter fun q => q.1.2 < q.2.2,
      (q.1.2 : ℤ) ^ i * ((q.2.2 : ℤ) - (q.1.2 : ℤ)) ^ j

private lemma phi_of_pos {j x : K} (h0 : x ≠ 0) (h1 : ‖x‖ < 1) :
    phi j x = x * (ofNormLtOne h0 h1).tateCurve.c₄ ^ 3
      / (j * (ofNormLtOne h0 h1).tateCurve.Δ)

private lemma norm_phi_sub_phi (h12 : (12 : K) ≠ 0) {j x y : K} (hj : 1 < ‖j‖)
    (hx0 : x ≠ 0) (hy0 : y ≠ 0) (hx : ‖x‖ = ‖j‖⁻¹) (hy : ‖y‖ = ‖j‖⁻¹) :
    ‖phi j x - phi j y‖ ≤ ‖j‖⁻¹ * ‖x - y‖

lemma IsWeightFamily.sub {t : TateParameter K} {k : ℕ} {A : Kˣ} {c d : ℤ → K}
    (hc : t.IsWeightFamily k A c) (hd : t.IsWeightFamily k A d) :
    t.IsWeightFamily k A (c - d)

private lemma YinnerFamily_eq (j m : ℕ) :
    t.YinnerFamily u (j, m)
      = ((m + 2).choose 2 : K) * (u : K) ^ (m + 2) * ((t.q : K) ^ (m + 2)) ^ (j + 1)

private lemma YouterFamily_eq (j m : ℕ) :
    t.YouterFamily u (j, m)
      = -(((m + 2).choose 2 : K) * ((u : K)⁻¹) ^ (m + 1) * ((t.q : K) ^ (m + 1)) ^ j)

private lemma norm_weight_kernel_le {F : K → K}
    (hF : ∀ {x : K}, ‖x‖ < 1 → ‖F x‖ ≤ ‖x‖) (c : ℕ → K) (hc : ∀ k, ‖c k‖ ≤ 1) (k : ℕ) :
    ‖c k * F ((t.q : K) ^ (k + 1))‖ ≤ ‖(t.q : K)‖ ^ (k + 1)

private lemma summable_weight_eisP_mul_eisR_qpow :
    Summable fun k : ℕ =>
      ((k + 1 : ℕ) : K) * (eisP ((t.q : K) ^ (k + 1)) * eisR ((t.q : K) ^ (k + 1)))

private lemma norm_eisenstein_term_le (k n : ℕ) :
    ‖((n + 1 : ℕ) : K) ^ k * (t.q : K) ^ (n + 1) / (1 - (t.q : K) ^ (n + 1))‖
      ≤ ‖(t.q : K)‖ ^ (n + 1)

private lemma hasSum_succ_of_hasSum {c : ℕ → K} {y S : K}
    (h : HasSum (fun j : ℕ => c j * y ^ j) S) (h0 : c 0 = 0) :
    HasSum (fun j : ℕ => c (j + 1) * y ^ (j + 1)) S

private lemma norm_sigma1_conv_le_one (m : ℕ) :
    ‖∑ r ∈ Finset.Ico 1 m, (∑ d ∈ r.divisors, (d : K)) * ∑ d ∈ (m - r).divisors, (d : K)‖
      ≤ 1

private lemma hAux_sub_sub (x a b : K) :
    t.hAux x b - t.hAux x a - (b - a) * t.dAux x a
      = (b - a) ^ 2 * (x + t.gAux a) + b ^ 2 * (t.gAux b - t.gAux a)

theorem norm_y_sq_eq_norm_x_cube (h12 : (12 : K) ≠ 0) {x y : K}
    (hxy : y ^ 2 + x * y = x ^ 3 + t.a₄ * x + t.a₆) (hx : 1 < ‖x‖) :
    ‖y‖ ^ 2 = ‖x‖ ^ 3

lemma point_some_congr {W : WeierstrassCurve.Affine K} {x₁ y₁ x₂ y₂ : K}
    {h₁ : W.Nonsingular x₁ y₁} {h₂ : W.Nonsingular x₂ y₂} (hx : x₁ = x₂) (hy : y₁ = y₂) :
    (WeierstrassCurve.Affine.Point.some x₁ y₁ h₁) = .some x₂ y₂ h₂

private lemma norm_term_le_of_norm_le {u : Kˣ} {n : ℤ}
    (h : ‖(t.q : K) ^ n * (u : K)‖ ≤ ‖(t.q : K)‖) :
    ‖t.Xterm u n‖ ≤ ‖(t.q : K)‖ ∧ ‖t.Yterm u n‖ ≤ ‖(t.q : K)‖

private lemma norm_term_le_of_inv_norm_le {u : Kˣ} {n : ℤ}
    (h : ‖(t.q : K)‖⁻¹ ≤ ‖(t.q : K) ^ n * (u : K)‖) :
    ‖t.Xterm u n‖ ≤ ‖(t.q : K)‖ ∧ ‖t.Yterm u n‖ ≤ ‖(t.q : K)‖

private lemma norm_term_le_annulus {u : Kˣ} (hlo : ‖(t.q : K)‖ < ‖(u : K)‖)
    (hhi : ‖(u : K)‖ < 1) {n : ℤ} (hn0 : n ≠ 0) (hn1 : n ≠ -1) :
    ‖t.Xterm u n‖ ≤ ‖(t.q : K)‖ ∧ ‖t.Yterm u n‖ ≤ ‖(t.q : K)‖

theorem mem_range_tatePoint_of_annulus {x y : K}
    (hns : t.tateCurve.toAffine.Nonsingular x y) (hx : ‖x‖ < 1) (hy : ‖y‖ < 1) :
    ∃ u : Kˣ, t.tatePoint hmem h12 u = WeierstrassCurve.Affine.Point.some x y hns

theorem defectAnnulusCoeff_eq_zero (h12 : (12 : K) ≠ 0) {u : Kˣ}
    (h1 : 1 < ‖(u : K)‖) (h2 : ‖(t.q : K)‖ * ‖(u : K)‖ < 1) (ℓ : ℤ) :
    t.defectAnnulusCoeff ℓ = 0

private lemma factor2_pointwise (u : Kˣ) (n : ℕ) :
    (1 : K) + (t.q : K) ^ n * ((t.q : K) * (u : K)) = 0 ↔
      (u : K) = -(t.q : K) ^ (-((n : ℤ) + 1))

theorem thetaProd_zero_orbit [CompleteSpace K] {u v : Kˣ}
    (hu : t.thetaProd u = 0) (hv : t.thetaProd v = 0) :
    ∃ k : ℤ, (u : K) = (t.q : K) ^ k * (v : K)

lemma const_eq_thetaProdLaurentCoeff_zero {b₀ : K}
    (hb₀ : ∀ u : Kˣ, t.thetaProd u = b₀ * t.theta u) :
    b₀ = t.thetaProdLaurentCoeff 0

private lemma hasSum_int_nonneg_support {f : ℤ → K} {S : K}
    (h0 : ∀ n : ℤ, n < 0 → f n = 0) (h : HasSum (fun k : ℕ => f (k : ℤ)) S) :
    HasSum f S

private lemma hasSum_int_nonpos_support {f : ℤ → K} {S : K}
    (h0 : ∀ n : ℤ, 0 < n → f n = 0) (h : HasSum (fun k : ℕ => f (-(k : ℤ))) S) :
    HasSum f S

private lemma hasSum_mul_zpow_shift {K : Type*} [NormedField K] (u : Kˣ) (d : ℤ)
    {f : ℤ → K} {S : K} (h : HasSum (fun m : ℤ => f m * (u : K) ^ m) S) :
    HasSum (fun m : ℤ => f (m - d) * (u : K) ^ m) (S * (u : K) ^ d)

private lemma hasSum_hFam (u : Kˣ) :
    HasSum (fun k : ℤ => t.hFam k * (u : K) ^ k)
      (t.thetaProdFactor (-((t.q : K) * (u : K))))

private lemma hasSum_aFam (p : ℕ) (u : Kˣ) :
    HasSum (fun k : ℤ => t.aFam p k * (u : K) ^ k)
      (t.pFactorSeries p (-((t.q : K) * (u : K))))

private lemma hasSum_bFam (p : ℕ) (u : Kˣ) :
    HasSum (fun m : ℤ => t.bFam p m * (u : K) ^ m)
      (t.pFactorSeries p (-((u : K))⁻¹))

private lemma theta_neg_eq (u : Kˣ) :
    t.theta (-u) = t.thetaProdFactor (-(t.q : K))
      * t.thetaProdFactor (-((t.q : K) * (u : K))) * t.thetaProdFactor (-((u : K))⁻¹)

private lemma hasSum_xFam_marginal (u : Kˣ) :
    HasSum (fun m : ℤ => (∑' n : ℤ, t.xFam n m) * (u : K) ^ m)
      (∑' p : ℤ × ℤ, t.xFam p.1 p.2 * (u : K) ^ p.2)

private lemma hasSum_yFam_marginal (u : Kˣ) :
    HasSum (fun m : ℤ => (∑' n : ℤ, t.yFam n m) * (u : K) ^ m)
      (∑' p : ℤ × ℤ, t.yFam p.1 p.2 * (u : K) ^ p.2)

private lemma hasSum_thetaNegSq (u : Kˣ) :
    HasSum (fun m : ℤ => lconv t.thetaNegCoeff t.thetaNegCoeff m * (u : K) ^ m)
      (t.theta (-u) * t.theta (-u))

theorem theta_eq_thetaProd_of_laurentCoeffUnique (huniq : LaurentCoeffUnique K) {u₀ : Kˣ}
    (hu₀ : t.theta u₀ ≠ 0) (hnorm : t.theta u₀ = t.thetaProd u₀) (u : Kˣ) :
    t.theta u = t.thetaProd u

private lemma weightExtend_fiber (hk : 0 < k) (v : Fin k → K) (i : ℕ) (hi : i < k) (m : ℤ) :
    weightExtend (t := t) hk A v ((i : ℤ) + k * m)
      = ((A⁻¹ : Kˣ) : K) ^ m * (t.q : K) ^ (m * i + k * thetaExp (m - 1)) * v ⟨i, hi⟩

theorem w1_eq_smul_thetaBlock {A : Kˣ} {c : ℤ → K}
    (hc : t.IsWeightFamily 1 A c) :
    c = c 0 • t.thetaBlock ((t.q * A)⁻¹)

private lemma witness_class_unique {y : Kˣ} {j₁ j₂ : ℕ} {n₁ n₂ : ℤ}
    (h₁ : ((t.sphereWitness j₁ : Kˣ) : K) = (t.q : K) ^ n₁ * (y : K))
    (h₂ : ((t.sphereWitness j₂ : Kˣ) : K) = (t.q : K) ^ n₂ * (y : K)) : j₁ = j₂

private lemma witness_sq_class_unique (h2 : ‖(2 : K)‖ = 1) {y : Kˣ} {j₁ j₂ : ℕ} {n₁ n₂ : ℤ}
    (h₁ : ((t.sphereWitness j₁ : Kˣ) : K) ^ 2 = (t.q : K) ^ n₁ * (y : K))
    (h₂ : ((t.sphereWitness j₂ : Kˣ) : K) ^ 2 = (t.q : K) ^ n₂ * (y : K)) : j₁ = j₂
